    public static void testNoiseGlyphsRulesAndLargeThingsAreToldApart() {
        emon.Port.Bitmap b = emon.Port.bitmapNew(200, 160, 1);
        emon.Port.Cells comps = emon.Port.newCells();
        emon.Port.Cells rules = emon.Port.newCells();
        emon.Port.Cells prims = emon.Port.newCells();
        emon.Port.Cells tlines = emon.Port.newCells();
        emon.Port.Cells pts = emon.Port.newCells();
        emon.Port.Cells refs = emon.Port.newCells();
        emon.Port.Cells views = emon.Port.newCells();
        emon.Port.Cells inks = emon.Port.newCells();
        int i = 0;
        int r = 0;
        // thirty glyph-sized blocks in three rows, a speck, a tall thin bar (a rule), a long thin one, and a big block
        while (r < 3) {
            i = 0;
            while (i < 10) {
                ttRect(b, 4 + (i * 10), 4 + (r * 12), 10 + (i * 10), 12 + (r * 12));
                i += 1;
            }
            r += 1;
        }
        ttDot(b, 190, 5);
        ttRect(b, 170, 60, 172, 90);
        ttRect(b, 4, 100, 150, 102);
        ttRect(b, 4, 110, 60, 148);
        ttTrace(b, 7200, comps, rules, prims, tlines, pts, refs, views, inks);
        emon.Testport.assertEq(Evidence.coCount(comps), 34, "thirty-four components");
        emon.Testport.assertEq(Evidence.coGet(comps, 0, Evidence.cfKind()), Evidence.ckTextLike(), "a glyph-sized block is text-like");
        emon.Testport.assertEq(Evidence.coGet(comps, 0, Evidence.cfConf()), 900, "with confidence 900");
        // sorted by top: the first row (y 4), the speck (y 5), the second and third rows, the tall bar, the long bar, the big block
        emon.Testport.assertEq(Evidence.coGet(comps, 10, Evidence.cfKind()), Evidence.ckBlob(), "the speck is blob (noise)");
        emon.Testport.assertEq(Evidence.coGet(comps, 10, Evidence.cfConf()), 0, "with confidence 0");
        emon.Testport.assertEq(Evidence.coGet(comps, 31, Evidence.cfKind()), Evidence.ckRuleV(), "the tall thin bar is a vertical rule");
        emon.Testport.assertEq(Evidence.coGet(comps, 32, Evidence.cfKind()), Evidence.ckRuleH(), "the long thin one is a horizontal rule");
        emon.Testport.assertEq(Evidence.coGet(comps, 33, Evidence.cfKind()), Evidence.ckBlob(), "the big block is large (blob)");
        emon.Testport.assertEq(Evidence.coGet(comps, 33, Evidence.cfConf()), 700, "with confidence 700");
    }
