    public static void testDouglasPeuckerDropsAStaircaseAndKeepsACorner() {
        emon.Port.Cells raw = emon.Port.newCells();
        emon.Port.Cells keep = emon.Port.newCells();
        emon.Port.Cells stk = emon.Port.newCells();
        // an open chain along a gentle line with one-pixel wobble, then a real corner
        emon.Port.cellsPush(raw, 0);
        emon.Port.cellsPush(raw, 0);
        emon.Port.cellsPush(raw, 5);
        emon.Port.cellsPush(raw, 1);
        emon.Port.cellsPush(raw, 10);
        emon.Port.cellsPush(raw, 0);
        emon.Port.cellsPush(raw, 15);
        emon.Port.cellsPush(raw, 1);
        emon.Port.cellsPush(raw, 20);
        emon.Port.cellsPush(raw, 0);
        emon.Testport.assertEq(Trace.trSimplify(raw, 5, 0, 9, keep, stk), 2, "the wobble is under 1.5 px: only the ends stay");
        emon.Port.cellsPush(raw, 20);
        emon.Port.cellsPush(raw, 20);
        emon.Testport.assertEq(Trace.trSimplify(raw, 6, 0, 9, keep, stk), 3, "a corner 20 px off the chord stays");
        emon.Testport.assertEq(emon.Port.cellsAt(keep, 5), 1, "the end");
        emon.Port.Cells sq = emon.Port.newCells();
        emon.Port.cellsPush(sq, 0);
        emon.Port.cellsPush(sq, 0);
        emon.Port.cellsPush(sq, 10);
        emon.Port.cellsPush(sq, 0);
        emon.Port.cellsPush(sq, 10);
        emon.Port.cellsPush(sq, 10);
        emon.Port.cellsPush(sq, 0);
        emon.Port.cellsPush(sq, 10);
        emon.Testport.assertEq(Trace.trSimplify(sq, 4, 1, 9, keep, stk), 4, "a closed square keeps its four corners");
    }
